class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        ans = 0
        for char in s:
            idx = ord(char) - ord('a')
            if t > 25 - idx:
                ans += 2
            else:
                ans += 1
        return ans % MOD

from typing import List
import math

class Solution:
    def maxLength(self, nums: List[int]) -> int:
        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        def lcm(a, b):
            if a == 0 or b == 0:
                return 0
            return abs(a * b) // gcd(a, b)

        n = len(nums)
        max_len = 0

        # Iterate over all possible subarrays
        for i in range(n):
            current_gcd = 0
            current_lcm = 0
            current_prod = 1

            # Extend the subarray from index i to j
            for j in range(i, n):
                x = nums[j]

                # Update GCD and LCM incrementally
                if current_gcd == 0:
                    current_gcd = x
                else:
                    current_gcd = gcd(current_gcd, x)

                if current_lcm == 0:
                    current_lcm = x
                else:
                    current_lcm = lcm(current_lcm, x)

                current_prod *= x

                # Check the product equivalent condition: prod(arr) == lcm(arr) * gcd(arr)
                if current_prod == current_lcm * current_gcd:
                    length = j - i + 1
                    if length > max_len:
                        max_len = length

        return max_len
